import{_ as o,o as a,c as r,a0 as l}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Cómo Solucionar Problemas de Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"es/how-to/07-solucionar-problemas.md","filePath":"es/how-to/07-solucionar-problemas.md"}'),c={name:"es/how-to/07-solucionar-problemas.md"};function s(n,e,d,i,t,u){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="como-solucionar-problemas-de-local-swmm" tabindex="-1">Cómo Solucionar Problemas de Local SWMM <a class="header-anchor" href="#como-solucionar-problemas-de-local-swmm" aria-label="Permalink to &quot;Cómo Solucionar Problemas de Local SWMM&quot;">​</a></h1><p>Arregla problemas comunes con el mapa, las simulaciones, el build de WASM, y conoce las particularidades de este codebase.</p><h2 id="como-arreglar-un-mapa-en-blanco-sin-teselas" tabindex="-1">Cómo arreglar un mapa en blanco / sin teselas <a class="header-anchor" href="#como-arreglar-un-mapa-en-blanco-sin-teselas" aria-label="Permalink to &quot;Cómo arreglar un mapa en blanco / sin teselas&quot;">​</a></h2><ul><li><code>public/config.js</code> falta o el token está vacío → créalo con un <code>MAPBOX_ACCESS_TOKEN</code> válido (consulta <a href="./02-configurar.html">Cómo Configurar Local SWMM</a>).</li><li>¿El navegador bloqueado por CSP? Revisa la consola en busca de violaciones de CSP contra <code>api.mapbox.com</code>.</li></ul><h2 id="como-arreglar-errores-de-run-inmediatos-con-una-advertencia" tabindex="-1">Cómo arreglar errores de &quot;Run&quot; inmediatos con una advertencia <a class="header-anchor" href="#como-arreglar-errores-de-run-inmediatos-con-una-advertencia" aria-label="Permalink to &quot;Cómo arreglar errores de &quot;Run&quot; inmediatos con una advertencia&quot;">​</a></h2><ul><li>Causa: no hay nodos o no hay un outfall en el modelo.</li><li>Solución: agrega al menos un nodo y un <code>OUTFALL</code> conectado a la red.</li></ul><h2 id="como-arreglar-una-corrida-que-falla-en-silencio-con-errores-del-motor" tabindex="-1">Cómo arreglar una corrida que falla en silencio / con errores del motor <a class="header-anchor" href="#como-arreglar-una-corrida-que-falla-en-silencio-con-errores-del-motor" aria-label="Permalink to &quot;Cómo arreglar una corrida que falla en silencio / con errores del motor&quot;">​</a></h2><ol><li>Revisa la ventana <strong>Run Status</strong> y luego la pestaña <strong>Report</strong>. Para diagnóstico profundo, el worker vuelca las líneas de error del <code>.rpt</code> y los primeros 3000 caracteres del INP al fallar (<code>simWorker.js</code>).</li><li>Reproduce en Node: <code>node scripts/bench-1d.mjs model.inp</code> imprime los códigos del motor (<code>SWMM_ERR_LIFECYCLE = 6</code> es el código de completado normal).</li></ol><h2 id="como-arreglar-un-build-de-wasm-que-falla-en-pluginfactory-cpp-46-unsupported-platform" tabindex="-1">Cómo arreglar un build de WASM que falla en <code>PluginFactory.cpp:46: unsupported platform</code> <a class="header-anchor" href="#como-arreglar-un-build-de-wasm-que-falla-en-pluginfactory-cpp-46-unsupported-platform" aria-label="Permalink to &quot;Cómo arreglar un build de WASM que falla en `PluginFactory.cpp:46: unsupported platform`&quot;">​</a></h2><ul><li>Causa: el submodule se re-fijó sin el commit de compatibilidad de wasm.</li><li>Solución: restaura <code>85e4be38</code> (consulta <a href="./03-compilar-desde-fuente.html">Cómo Compilar el Motor WASM desde el Código Fuente</a>, sección 5) o vuelve a aplicar los no-ops de Emscripten.</li></ul><h2 id="como-arreglar-could-not-find-zip-durante-el-bootstrap-de-vcpkg" tabindex="-1">Cómo arreglar <code>Could not find zip</code> durante el bootstrap de vcpkg <a class="header-anchor" href="#como-arreglar-could-not-find-zip-durante-el-bootstrap-de-vcpkg" aria-label="Permalink to &quot;Cómo arreglar `Could not find zip` durante el bootstrap de vcpkg&quot;">​</a></h2><ul><li>Causa: falta <code>zip</code>/<code>unzip</code>/<code>tar</code> del sistema.</li><li>Solución: en Arch Linux: <code>sudo pacman -S zip unzip tar</code>; en Debian/Ubuntu: <code>sudo apt install zip unzip tar</code>.</li></ul><h2 id="como-arreglar-wasm-obsoleto-servido-en-cache" tabindex="-1">Cómo arreglar wasm obsoleto servido en caché <a class="header-anchor" href="#como-arreglar-wasm-obsoleto-servido-en-cache" aria-label="Permalink to &quot;Cómo arreglar wasm obsoleto servido en caché&quot;">​</a></h2><ul><li>El servidor envía <code>Cache-Control: no-store</code>, pero si estás alojando en otro lado, haz un refresh forzado después de recompilar (se usan parámetros de query <code>swmm6wasm.js?v=&lt;n&gt;</code> en <code>index.html</code>).</li></ul><h2 id="trampas-y-particularidades-conocidas" tabindex="-1">Trampas y particularidades conocidas <a class="header-anchor" href="#trampas-y-particularidades-conocidas" aria-label="Permalink to &quot;Trampas y particularidades conocidas&quot;">​</a></h2><ol><li><strong>Deriva histórica del README:</strong> El inicio rápido del README referenció anteriormente <code>cd SWMM_3D_Web_UI</code> y <code>http://localhost:8000</code>; el directorio es <code>LocalSWMM</code> y el puerto del servidor es <code>8080</code>.</li><li><strong>Nombres de binarios del motor:</strong> El motor WebAssembly activo se entrega mediante <code>swmm6wasm.js</code> y <code>swmm6wasm.wasm</code>, cargados por <code>simWorker.js</code>.</li><li><strong>Mensajes de progreso de <code>simWorker</code>:</strong> El worker calcula asíncronamente en bucles de stride; la barra de progreso entrega retroalimentación visual durante el cómputo.</li><li><strong>Parseo de salida binaria:</strong> <code>swmmOutParser.js</code> parsea los binarios <code>.out</code> para máximo rendimiento, con fallback al reporte de texto <code>.rpt</code> para tablas resumen.</li><li><strong>Comentario en <code>bench-1d.mjs</code>:</strong> <code>bench-1d.mjs</code> conserva un comentario de cabecera que hace referencia a <code>probe-1d.mjs</code>.</li><li><strong>Parámetros de capas LID:</strong> Los parámetros de capa LID se preservan en <code>rawSections</code> (<code>inpParser.js</code>) para garantizar la persistencia fiel en exportaciones INP.</li><li><strong>Declaraciones de configuración:</strong> El <code>config.js</code> de CI usa <code>const CONFIG</code> mientras que las configuraciones locales usan <code>var</code>; las búsquedas de <code>window.CONFIG</code> son defensivas en ambos casos.</li><li><strong>Capas del manifiesto de vcpkg:</strong> El <code>vcpkg.json</code> propio del motor se ignora para el build de WASM; solo se aplica el manifiesto raíz.</li></ol>',16)])])}const g=o(c,[["render",s]]);export{p as __pageData,g as default};
